from pathlib import Path
import html
import json

from hinglish_app import BRIDGE_URL
from .styles import FONT_CHOICES, TEMPLATES, template


def _safe_json(value):
    return json.dumps(value, ensure_ascii=False).replace('<', '\\u003c')


def write_report(path, media_name, video_relative, cues, style_name, files, project=None):
    path = Path(path)
    style = template(style_name)
    project = dict(project or {})
    payload = [{'start': c.start, 'end': c.end,
                'words': [{'text': w.text, 'start': w.start, 'end': w.end} for w in c.words]} for c in cues]
    project['project_path'] = str((path.parent / 'caption-project.json').resolve())
    links = ''.join(f'<a href="{html.escape(name)}">{html.escape(label)}</a>' for label, name in files)
    templates = ''.join(
        f'<button class="template-card" data-style="{key}" data-category="{value["category"]}">'
        f'<div class="template-sample {key}">this is how you go <em>viral</em></div>'
        f'<b>{html.escape(value["name"])}</b><small>{html.escape(value["tag"])}</small></button>'
        for key, value in TEMPLATES.items())
    fonts = ''.join(f'<option value="{key}">{html.escape(value["name"])}</option>'
                    for key, value in FONT_CHOICES.items())
    cue_editors = ''.join(
        f'<label class="cue-row" data-index="{index}"><span>{index + 1}</span>'
        f'<small>{cue.start:.2f}–{cue.end:.2f}</small>'
        f'<textarea rows="2">{html.escape(cue.text)}</textarea></label>'
        for index, cue in enumerate(cues))
    duration = max((cue.end for cue in cues), default=1)
    caption_blocks = ''.join(
        f'<button style="left:{cue.start / duration * 100:.3f}%;width:{max(.3, (cue.end - cue.start) / duration * 100):.3f}%" data-seek="{cue.start}">{html.escape(cue.text)}</button>'
        for cue in cues)
    document = f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Caption Studio · {html.escape(media_name)}</title><style>
:root{{--accent:#ff6635;--caption-accent:#ff7638;--line:#302d29;--panel:#151412;--muted:#8e8982}}*{{box-sizing:border-box}}body{{margin:0;background:#0c0b0a;color:#f8f5ef;font:14px/1.4 "Segoe UI",Arial,sans-serif;overflow:hidden}}button,textarea,select,input{{font:inherit}}header{{height:58px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 18px}}header b{{font-size:17px}}header small{{color:var(--muted);margin-left:12px}}.ratios{{display:flex;border:1px solid var(--line);border-radius:9px;padding:3px;gap:3px}}.ratios button,.tabbar button,.chips button{{border:0;background:transparent;color:#aaa49b;border-radius:6px;padding:7px 12px;cursor:pointer}}.ratios button.active,.tabbar button.active,.chips button.active{{background:#292622;color:#fff}}.save{{background:var(--accent);border:0;color:#180b06;font-weight:800;border-radius:9px;padding:10px 18px;cursor:pointer}}.app{{height:calc(100vh - 58px);display:grid;grid-template-columns:minmax(0,1fr) 340px;grid-template-rows:minmax(0,1fr) 205px;gap:10px;padding:10px}}.preview{{position:relative;display:grid;place-items:center;background:#090909;border:1px solid var(--line);border-radius:13px;overflow:hidden}}.stage{{position:relative;height:min(72vh,100%);max-width:94%;aspect-ratio:16/9;background:#000;overflow:hidden}}.stage.vertical{{aspect-ratio:9/16}}.stage.square{{aspect-ratio:1/1}}video{{position:absolute;inset:0;width:100%;height:100%;object-fit:contain}}#caption{{position:absolute;left:5%;right:5%;top:70%;transform:translateY(-50%);text-align:center;font-size:clamp(23px,4.4vw,62px);font-weight:900;line-height:1.02;text-shadow:0 4px 14px #000,0 2px 2px #000;-webkit-text-stroke:1px #111;pointer-events:none}}#caption span{{display:inline-block;margin:0 .08em;transition:.08s}}#caption span.active{{color:var(--caption-accent);transform:scale(1.1)}}#caption.surface{{display:inline-block;left:50%;right:auto;transform:translate(-50%,-50%);padding:.18em .35em;border-radius:.18em;text-shadow:none;-webkit-text-stroke:0;white-space:nowrap}}#caption.one-word span:not(.active){{display:none}}#caption.script-active span.active{{font-family:"Segoe Script",cursive;font-weight:700}}.sidebar{{grid-row:1/3;grid-column:2;background:var(--panel);border:1px solid var(--line);border-radius:13px;overflow:hidden;display:flex;flex-direction:column}}.tabbar{{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid var(--line);padding:8px}}.pane{{padding:12px;overflow:auto;min-height:0}}.chips{{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:11px}}.chips button{{border:1px solid var(--line);padding:5px 9px;font-size:11px}}.template-list{{display:grid;gap:9px}}.template-card{{background:#11100f;color:#fff;border:1px solid #37322d;border-radius:11px;padding:0;text-align:left;overflow:hidden;cursor:pointer}}.template-card.active{{border:2px solid var(--accent)}}.template-sample{{height:82px;display:grid;place-content:center;text-align:center;font-size:18px;font-weight:900;padding:8px}}.template-sample em{{color:#fff200;font-style:normal}}.template-card b,.template-card small{{display:inline-block;padding:9px 10px}}.template-card small{{float:right;color:#77716a}}.soft_focus em,.aura_script em{{font-family:"Segoe Script",cursive;color:#ff5a45;font-weight:500}}.signal_bar em,.focus_signal em{{background:#087df5;color:#fff;padding:2px 5px}}.real_estate em{{font-size:30px;color:#d7ff23}}.text-controls{{display:grid;gap:12px;margin-bottom:14px;padding:12px;background:#11100f;border:1px solid var(--line);border-radius:10px}}.text-controls label{{display:grid;gap:5px;color:#aaa49b;font-size:11px}}select,textarea{{background:#0e0d0c;color:#fff;border:1px solid #37322d;border-radius:7px;padding:8px}}.cue-list{{display:grid;gap:8px}}.cue-row{{display:grid;grid-template-columns:25px 70px 1fr;gap:6px;align-items:start;padding:8px;border:1px solid var(--line);border-radius:9px}}.cue-row:focus-within{{border-color:var(--accent)}}.cue-row>span{{color:var(--accent)}}.cue-row small{{color:#b6b0a8}}.cue-row textarea{{grid-column:1/-1;width:100%;resize:vertical}}.timeline{{position:relative;border:1px solid var(--line);border-radius:13px;background:#11100f;padding:42px 16px 12px 62px;overflow:hidden}}.transport{{position:absolute;top:8px;left:14px;display:flex;gap:8px;align-items:center}}.transport button{{background:#f7f3eb;border:0;border-radius:7px;padding:7px 11px;cursor:pointer}}.transport span{{color:#aaa49b}}.track{{height:38px;position:relative;border-top:1px solid #292621;margin-bottom:7px;background:#0b0a09}}.track:before{{position:absolute;right:calc(100% + 10px);top:10px;color:#8b857d;font-size:10px;letter-spacing:.12em}}.track.video:before{{content:'VID'}}.track.captions:before{{content:'CAP'}}.track.audio:before{{content:'AUD'}}.track.video div,.track.audio div{{position:absolute;inset:4px;background:#3a2d20;border-radius:5px}}.track.audio div{{background:repeating-linear-gradient(90deg,#29536a 0 2px,#122d3a 2px 5px)}}.track.captions button{{position:absolute;top:4px;height:30px;border:0;border-radius:4px;background:#5e2b1d;color:#fff;font-size:9px;overflow:hidden;white-space:nowrap;cursor:pointer}}.links{{display:flex;gap:7px;position:absolute;right:14px;top:8px}}.links a{{color:#ddd;text-decoration:none;border:1px solid var(--line);border-radius:7px;padding:6px 8px;font-size:10px}}#status{{color:#a9d8ba;font-size:11px}}.hidden{{display:none!important}}@media(max-width:900px){{body{{overflow:auto}}.app{{height:auto;display:block}}.preview{{height:70vh}}.sidebar{{margin-top:10px;height:680px}}.timeline{{height:205px;margin-top:10px}}}}
</style><style>.template-sample.typography_1{{font-family:Impact,sans-serif;letter-spacing:.03em}}.template-sample.typography_1 em{{background:#f12722;color:#fff;padding:2px 7px;box-shadow:7px 6px 18px #f1272277}}#caption.typography-one{{display:flex;flex-direction:column;align-items:center;justify-content:center;left:3%;right:3%;gap:.025em;line-height:.84;text-shadow:none;-webkit-text-stroke:0;filter:drop-shadow(0 8px 13px #000)}}#caption.typography-one .t1-line{{display:block;max-width:96%;white-space:nowrap;font-family:Impact,sans-serif;color:#fff;text-shadow:.05em .06em 0 #050505,0 .08em .18em #000;letter-spacing:.015em}}#caption.typography-one .t1-small{{font:700 .27em/1 Arial,sans-serif;letter-spacing:.10em}}#caption.typography-one .t1-big{{font-size:.92em}}#caption.typography-one .t1-giant{{font-size:1.16em}}#caption.typography-one .t1-bar{{background:var(--t1-color,#f12722);padding:.035em .15em;box-shadow:-.10em .08em 0 var(--t1-deep,#870b0b),0 0 .28em color-mix(in srgb,var(--t1-color,#f12722) 58%,transparent)}}#caption.typography-one .t1-outline{{font-size:1.15em;color:transparent;-webkit-text-stroke:.025em #fff;opacity:.32;margin-top:-.18em}}#caption.typography-one .t1-script{{font:700 .48em/1 "Segoe Script",cursive;text-transform:none;transform:rotate(-3deg);margin-bottom:.12em}}#caption.typography-one .t1-line:nth-child(2){{z-index:2}}</style></head><body>
<header><div><b>Hinglish Caption Studio</b><small>{html.escape(media_name)}</small></div><div class="ratios"><button data-format="instagram_vertical">9:16</button><button data-format="square">1:1</button><button data-format="youtube_horizontal">16:9</button></div><div><span id="status">Ready to edit</span> <button id="save" class="save">Save &amp; rebuild</button></div></header>
<main class="app"><section class="preview"><div id="stage" class="stage"><video id="video" controls src="{html.escape(video_relative)}"></video><div id="caption"></div></div></section>
<aside class="sidebar"><div class="tabbar"><button class="active" data-tab="templates">Templates</button><button data-tab="text">Text &amp; words</button></div>
<div id="templatesPane" class="pane"><div class="chips"><button class="active" data-category="all">All</button><button data-category="cinematic">Cinematic</button><button data-category="aesthetic">Aesthetic</button><button data-category="boxed">Boxed</button><button data-category="editorial">Editorial</button><button data-category="oneword">One word</button></div><div class="template-list">{templates}</div></div>
<div id="textPane" class="pane hidden"><div class="text-controls"><label>Font<select id="font">{fonts}</select></label><label>Vertical position <input id="position" type="range" min="10" max="92" value="70"></label><label>Text size <input id="size" type="range" min="55" max="180" value="100"></label></div><div class="cue-list">{cue_editors}</div></div></aside>
<section class="timeline"><div class="transport"><button id="play">▶</button><span id="time">0:00 / {duration:.1f}s</span></div><div class="links">{links}</div><div class="track video"><div></div></div><div class="track captions">{caption_blocks}</div><div class="track audio"><div></div></div></section></main>
<script>
const cues={_safe_json(payload)},templates={_safe_json(TEMPLATES)},fonts={_safe_json(FONT_CHOICES)},project={_safe_json(project)};
let currentStyle=project.style||'{style_name}',currentFormat=project.output_format||'source';
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),video=$('#video'),caption=$('#caption'),stage=$('#stage');
function currentTexts(){{return [...$$('.cue-row textarea')].map(x=>x.value.trim())}}
function wordsFor(q){{const edited=currentTexts()[cues.indexOf(q)]||'';return edited.split(/\\s+/).filter(Boolean)}}
function applyStyle(){{const t=templates[currentStyle],templateFonts={{'impact.ttf':'Impact, sans-serif','arialbd.ttf':'Arial, sans-serif','bahnschrift.ttf':'Bahnschrift, sans-serif','segoeuib.ttf':'Segoe UI, sans-serif','georgiab.ttf':'Georgia, serif','segoesc.ttf':'Segoe Script, cursive','trebucbd.ttf':'Trebuchet MS, sans-serif'}},chosen=$('#font').value;caption.style.color=t.base;caption.style.background=t.surface||'transparent';document.documentElement.style.setProperty('--caption-accent',t.accent);caption.className=(t.surface?'surface ':'')+(t.one_word?'one-word ':'')+(t.active_font?'script-active ':'')+(t.layout==='typography_1'?'typography-one ':'');caption.style.fontFamily=chosen==='template'?(templateFonts[t.font]||'inherit'):(fonts[chosen]?.css||'inherit');caption.style.top=$('#position').value+'%';caption.style.fontSize=t.layout==='typography_1'?`calc(clamp(48px,8.8vw,138px) * ${{Number($('#size').value)/100}})`:`calc(clamp(23px,4.4vw,62px) * ${{Number($('#size').value)/100}})`;$$('.template-card').forEach(x=>x.classList.toggle('active',x.dataset.style===currentStyle))}}
function esc(value){{return value.replace(/[&<>]/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;'}}[c]))}}
function splitType(words,count){{const rows=[];for(let i=0;i<count;i++)rows.push(words.slice(Math.round(i*words.length/count),Math.round((i+1)*words.length/count)).join(' '));return rows}}
function typeLine(kind,text){{return text?`<span class="t1-line ${{kind}}">${{esc(text.toUpperCase())}}</span>`:''}}
function typographyMarkup(words,q){{const variant=Math.round(q.start*30)%8,hero=words.reduce((best,word,index)=>word.replace(/[^a-z0-9]/gi,'').length>words[best].replace(/[^a-z0-9]/gi,'').length?index:best,0);if(variant===0){{const setup=words.slice(0,-2).join(' '),bars=words.slice(-2);return typeLine('t1-small',setup)+bars.map(x=>typeLine('t1-giant t1-bar',x)).join('')}}if(variant===1){{const rows=splitType(words,2);return typeLine('t1-big',rows[0])+typeLine('t1-giant t1-bar',rows[1])}}if(variant===2)return typeLine('t1-small',words.slice(0,hero).join(' '))+typeLine('t1-giant t1-bar',words[hero])+typeLine('t1-small',words.slice(hero+1).join(' '));if(variant===3)return typeLine('t1-giant',words[hero])+typeLine('t1-outline',words[hero])+typeLine('t1-small',words.filter((_,i)=>i!==hero).join(' '));if(variant===4){{const rest=words.slice(1),middle=rest.length>3?rest.slice(0,-2).join(' '):'',answer=rest.length>3?rest.slice(-2).join(' '):rest.join(' ');return typeLine('t1-script',words[0])+typeLine('t1-big',middle)+typeLine('t1-giant t1-bar',answer)}}if(variant===5){{const rows=splitType(words,Math.min(3,words.length));return rows.map((row,index)=>typeLine(index===rows.length-1?'t1-big t1-bar':'t1-big',row)).join('')}}if(variant===6){{const numeric=words.findIndex(word=>/\d/.test(word)),focus=numeric>=0?numeric:hero;return typeLine('t1-small',words.slice(0,focus).join(' '))+typeLine('t1-giant t1-bar',words[focus])+typeLine('t1-small',words.slice(focus+1).join(' '))}}const rows=splitType(words,2);return typeLine('t1-big',rows[0])+typeLine('t1-giant t1-bar',rows[1])}}
function previewMotion(t,q,now){{if(t.layout!=='typography_1'){{caption.style.transform='translateY(-50%)';caption.style.filter='';caption.style.opacity='1';return}}const intro=Math.min(1,Math.max(0,(now-q.start)/.30)),outro=Math.min(1,Math.max(0,(q.end-now)/.28)),direction=Math.round(q.start*10)%2?-1:1,scale=.82+.18*intro+.08*(1-outro),blur=12*(1-intro)+9*(1-outro),colors=[['#f12722','#870b0b'],['#f4b400','#9a6500'],['#1769f5','#07388f']],seed=Math.round(q.start*100),color=colors[seed%3];caption.style.setProperty('--t1-color',color[0]);caption.style.setProperty('--t1-deep',color[1]);caption.style.transform=`translateY(-50%) translateX(${{direction*(1-intro)*10}}%) scale(${{scale}})`;caption.style.filter=`blur(${{blur}}px) drop-shadow(0 8px 13px #000)`;caption.style.opacity=String(Math.min(1,intro*1.4,outro*1.35));caption.querySelectorAll('.t1-line').forEach((line,index)=>{{const reveal=Math.min(1,Math.max(0,(now-q.start-index*.10)/.22));line.style.opacity=String(reveal);line.style.clipPath=`inset(0 ${{(1-reveal)*100}}% 0 0)`;line.style.transform=`translateX(${{(index%2?1:-1)*(1-reveal)*.22}}em)`}})}}
function draw(){{const now=video.currentTime,q=cues.find(x=>x.start<=now&&now<x.end);if(!q){{caption.innerHTML='';return}}const t=templates[currentStyle],words=wordsFor(q);let active=Math.min(words.length-1,Math.max(0,Math.floor((now-q.start)/Math.max(.01,q.end-q.start)*words.length)));caption.innerHTML=t.layout==='typography_1'?typographyMarkup(words,q):words.map((word,index)=>{{const shown=t.case==='upper'?word.toUpperCase():word;return `<span class="${{index===active?'active':''}}">${{esc(shown)}}</span>`}}).join(' ');applyStyle();previewMotion(t,q,now)}}
function setFormat(value,displayOnly=false){{if(!displayOnly)currentFormat=value;stage.className='stage '+(value==='instagram_vertical'?'vertical':value==='square'?'square':'');$$('.ratios button').forEach(x=>x.classList.toggle('active',x.dataset.format===value));draw()}}
$$('.template-card').forEach(x=>x.onclick=()=>{{currentStyle=x.dataset.style;draw()}});$$('.chips button').forEach(x=>x.onclick=()=>{{$$('.chips button').forEach(b=>b.classList.toggle('active',b===x));$$('.template-card').forEach(card=>card.classList.toggle('hidden',x.dataset.category!=='all'&&card.dataset.category!==x.dataset.category))}});$$('.tabbar button').forEach(x=>x.onclick=()=>{{$$('.tabbar button').forEach(b=>b.classList.toggle('active',b===x));$('#templatesPane').classList.toggle('hidden',x.dataset.tab!=='templates');$('#textPane').classList.toggle('hidden',x.dataset.tab!=='text')}});$$('.ratios button').forEach(x=>x.onclick=()=>setFormat(x.dataset.format));$$('[data-seek]').forEach(x=>x.onclick=()=>{{video.currentTime=Number(x.dataset.seek);video.play()}});$$('.cue-row').forEach(row=>row.onclick=e=>{{if(e.target.tagName!=='TEXTAREA')video.currentTime=cues[Number(row.dataset.index)].start}});
$('#font').value=project.font||'template';$('#position').value=Math.round((project.position||.70)*100);$('#size').value=Math.round((project.size||1)*100);['input','change'].forEach(event=>{{$('#font').addEventListener(event,draw);$('#position').addEventListener(event,draw);$('#size').addEventListener(event,draw)}});$$('.cue-row textarea').forEach(x=>x.addEventListener('input',draw));video.addEventListener('timeupdate',()=>{{draw();$('#time').textContent=`${{video.currentTime.toFixed(1)}}s / ${{video.duration?video.duration.toFixed(1):'?'}}s`}});video.addEventListener('seeked',draw);$('#play').onclick=()=>video.paused?video.play():video.pause();
async function save(){{const button=$('#save'),status=$('#status');button.disabled=true;status.textContent='Rebuilding caption layer…';try{{const bridge=await (await fetch('{BRIDGE_URL}/api/bridge')).json();const response=await fetch('{BRIDGE_URL}/api/captions/rebuild',{{method:'POST',headers:{{'Content-Type':'application/json','X-Hinglish-Token':bridge.token}},body:JSON.stringify({{project_path:project.project_path,texts:currentTexts(),style:currentStyle,font:$('#font').value,position:Number($('#position').value)/100,size:Number($('#size').value)/100,output_format:currentFormat}})}});const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not rebuild captions');status.textContent='Saved — XML and caption layer updated';setTimeout(()=>location.reload(),900)}}catch(error){{status.textContent=error.message;button.disabled=false}}}}$('#save').onclick=save;const displayFormat=currentFormat==='source'?(project.width<project.height?'instagram_vertical':'youtube_horizontal'):currentFormat;setFormat(displayFormat,currentFormat==='source');applyStyle();draw();
</script></body></html>'''
    path.write_text(document, encoding='utf-8')


def write_index(path, results, errors):
    cards = ''.join(f'<a href="{html.escape(row["folder"])}/report.html"><b>{html.escape(row["name"])}</b><span>{row["cues"]} caption phrases · {html.escape(row["style"])}</span></a>' for row in results)
    issues = ''.join(f'<li>{html.escape(e["source"])}: {html.escape(e["error"])}</li>' for e in errors)
    Path(path).write_text(f'''<!doctype html><html><head><meta charset="utf-8"><title>Premium Hinglish Captions</title><style>body{{background:#0d0f12;color:#fff;font:16px Segoe UI;margin:40px auto;max-width:850px;padding:0 20px}}h1{{font-size:42px}}p,span{{color:#9ca3ad}}main{{display:grid;gap:12px;margin-top:30px}}a{{display:flex;justify-content:space-between;background:#1b1f25;border:1px solid #30353d;border-radius:12px;padding:18px;color:#fff;text-decoration:none}}li{{color:#ff9b70}}</style></head><body><p>HINGLISH EDITOR</p><h1>Premium captions ready</h1><p>Open a video to edit every word, template, font, position, size and aspect ratio.</p><main>{cards}</main><ul>{issues}</ul></body></html>''', encoding='utf-8')
